// Task 0143: the .fuz container reader, on generated bytes (no game files). Written before the implementation.
#include <components/fuz/fuz.hpp>

#include <gtest/gtest.h>

#include <cstdint>
#include <string>

namespace
{
    void put32(std::string& s, std::uint32_t v)
    {
        for (int i = 0; i < 4; ++i)
            s.push_back(static_cast<char>((v >> (8 * i)) & 0xff));
    }

    /// A RIFF file: "RIFF", size, form type, `payload`. `declared` overrides the size field when not ~0.
    std::string riff(const std::string& form, const std::string& payload, std::uint32_t declared = 0xFFFFFFFFu)
    {
        std::string s = "RIFF";
        put32(s, declared != 0xFFFFFFFFu ? declared : static_cast<std::uint32_t>(4 + payload.size()));
        s += form;
        s += payload;
        return s;
    }

    std::string fuz(const std::string& lip, const std::string& audio, std::uint32_t version = 1,
        std::uint32_t lipSize = 0xFFFFFFFFu, const char* magic = "FUZE")
    {
        std::string s = magic;
        put32(s, version);
        put32(s, lipSize != 0xFFFFFFFFu ? lipSize : static_cast<std::uint32_t>(lip.size()));
        return s + lip + audio;
    }

    TEST(Fuz, splitsTheLipPartFromTheXwmaAudio)
    {
        const std::string audio = riff("XWMA", "fmt data");
        const std::string bytes = fuz("LIPDATA", audio);
        const Fuz::Result r = Fuz::split(bytes, "a.fuz");
        ASSERT_TRUE(r.mOk) << r.mError;
        EXPECT_EQ(r.mParts.mLip, "LIPDATA");
        EXPECT_EQ(r.mParts.mAudio, audio);
        EXPECT_TRUE(r.mParts.mAudioIsXwma);
        EXPECT_EQ(r.mParts.mTrailingBytes, 0u);
        EXPECT_TRUE(r.mError.empty());
    }

    TEST(Fuz, anEmptyLipPartIsLegal)
    {
        const std::string audio = riff("XWMA", "x");
        const Fuz::Result r = Fuz::split(fuz("", audio));
        ASSERT_TRUE(r.mOk) << r.mError;
        EXPECT_TRUE(r.mParts.mLip.empty());
        EXPECT_EQ(r.mParts.mAudio, audio);
    }

    TEST(Fuz, theResultPointsIntoTheCallersBytes)
    {
        const std::string bytes = fuz("LL", riff("XWMA", "abc"));
        const Fuz::Result r = Fuz::split(bytes);
        ASSERT_TRUE(r.mOk);
        EXPECT_EQ(r.mParts.mLip.data(), bytes.data() + 12);
        EXPECT_EQ(r.mParts.mAudio.data(), bytes.data() + 14);
    }

    TEST(Fuz, aWaveFormIsSplitButNotMarkedXwma)
    {
        const Fuz::Result r = Fuz::split(fuz("", riff("WAVE", "pcm")));
        ASSERT_TRUE(r.mOk) << r.mError;
        EXPECT_FALSE(r.mParts.mAudioIsXwma);
    }

    TEST(Fuz, bytesAfterTheDeclaredRiffSizeAreDroppedAndCounted)
    {
        const std::string audio = riff("XWMA", "abcd");
        const Fuz::Result r = Fuz::split(fuz("", audio + "JUNK!"));
        ASSERT_TRUE(r.mOk) << r.mError;
        EXPECT_EQ(r.mParts.mAudio, audio);
        EXPECT_EQ(r.mParts.mTrailingBytes, 5u);
    }

    TEST(Fuz, aRiffSizeLargerThanTheBytesPresentIsRefusedWithAnOffset)
    {
        const Fuz::Result r = Fuz::split(fuz("", riff("XWMA", "abcd", 1000)), "cut.fuz");
        EXPECT_FALSE(r.mOk);
        EXPECT_NE(r.mError.find("cut.fuz"), std::string::npos) << r.mError;
        EXPECT_NE(r.mError.find("offset"), std::string::npos) << r.mError;
    }

    TEST(Fuz, aRiffSizeSmallerThanTheFormTypeIsRefused)
    {
        EXPECT_FALSE(Fuz::split(fuz("", riff("XWMA", "abcd", 2))).mOk);
    }

    TEST(Fuz, aWrongMagicOrVersionIsRefused)
    {
        const std::string audio = riff("XWMA", "x");
        EXPECT_FALSE(Fuz::split(fuz("", audio, 1, 0xFFFFFFFFu, "FUZZ")).mOk);
        EXPECT_FALSE(Fuz::split(fuz("", audio, 2)).mOk);
        EXPECT_FALSE(Fuz::split(fuz("", audio, 0)).mOk);
    }

    TEST(Fuz, aLipSizePastTheEndOrOverTheLimitIsRefused)
    {
        const std::string audio = riff("XWMA", "x");
        EXPECT_FALSE(Fuz::split(fuz("", audio, 1, 100000)).mOk);
        EXPECT_FALSE(Fuz::split(fuz("", audio, 1, 0xFFFFFFFEu)).mOk);
        Fuz::Limits limits;
        limits.mMaxLipBytes = 3;
        EXPECT_FALSE(Fuz::split(fuz("LIPDATA", audio), "", limits).mOk);
        limits.mMaxLipBytes = 7;
        EXPECT_TRUE(Fuz::split(fuz("LIPDATA", audio), "", limits).mOk);
    }

    TEST(Fuz, audioThatIsNotARiffFileIsRefused)
    {
        EXPECT_FALSE(Fuz::split(fuz("", "OggS....")).mOk);
        EXPECT_FALSE(Fuz::split(fuz("", "")).mOk);
        EXPECT_FALSE(Fuz::split(fuz("", "RIFF")).mOk);
        EXPECT_FALSE(Fuz::split(fuz("", "RIFF\x04\0\0\0XWM")).mOk);
    }

    TEST(Fuz, everyTruncationIsRefusedNeverRead)
    {
        const std::string bytes = fuz("LIPDATA", riff("XWMA", "0123456789"));
        const Fuz::Result whole = Fuz::split(bytes);
        ASSERT_TRUE(whole.mOk);
        for (std::size_t n = 0; n < bytes.size(); ++n)
        {
            // Cutting inside the RIFF part leaves a declared size larger than the bytes: refused. Cutting nothing off
            // is the whole file.
            EXPECT_FALSE(Fuz::split(std::string_view(bytes.data(), n)).mOk) << "length " << n;
        }
    }

    TEST(Fuz, aFileOverTheByteCapIsRefusedBeforeItIsLookedAt)
    {
        const std::string bytes = fuz("", riff("XWMA", std::string(100, 'a')));
        Fuz::Limits limits;
        limits.mMaxBytes = bytes.size() - 1;
        EXPECT_FALSE(Fuz::split(bytes, "", limits).mOk);
        limits.mMaxBytes = bytes.size();
        EXPECT_TRUE(Fuz::split(bytes, "", limits).mOk);
    }

    TEST(Fuz, theMagicTestIsCheapAndExact)
    {
        EXPECT_TRUE(Fuz::hasFuzMagic("FUZE...."));
        EXPECT_FALSE(Fuz::hasFuzMagic("FUZ"));
        EXPECT_FALSE(Fuz::hasFuzMagic("RIFFXWMA"));
        EXPECT_FALSE(Fuz::hasFuzMagic(""));
    }

    TEST(Fuz, randomBytesNeverCrashAndNeverClaimMoreThanTheyHold)
    {
        std::uint64_t state = 0x9E3779B97F4A7C15ull;
        const auto next = [&] {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            return state;
        };
        const std::string seed = fuz("LIP", riff("XWMA", "payload-bytes"));
        for (int i = 0; i < 20000; ++i)
        {
            std::string bytes = seed;
            const int edits = 1 + static_cast<int>(next() % 4);
            for (int e = 0; e < edits; ++e)
                bytes[next() % bytes.size()] = static_cast<char>(next());
            const Fuz::Result r = Fuz::split(bytes);
            if (r.mOk)
            {
                EXPECT_LE(r.mParts.mLip.size() + r.mParts.mAudio.size() + 12, bytes.size());
                EXPECT_GE(r.mParts.mLip.data(), bytes.data());
                EXPECT_LE(r.mParts.mAudio.data() + r.mParts.mAudio.size(), bytes.data() + bytes.size());
            }
        }
    }
}
